import assert from 'node:assert/strict';
import { createProgressFeed, createTransferWorkspace, collectProgressTelemetry } from './src/workspace.js';

// A warm packet is shown immediately, then ordinary live packets stream normally.
{
  const shown = [];
  const recorded = [];
  const feed = createProgressFeed({ initialPacket: { progress: 10 } });
  const workspace = createTransferWorkspace({
    transport() {}, onCancel() {}, record() {}, showQueued() {},
    recordProgress: value => recorded.push(value),
    showProgress: value => shown.push(value),
  });
  workspace.select({ id: 'warm', progressFeed: feed });
  feed.emit({ progress: 20 });
  assert.deepEqual(shown.map(value => value.frame.progress), [10, 20]);
  assert.deepEqual(recorded.map(value => value.frame.progress), [10, 20]);
}

// Source order, rather than decode completion order, controls the display.
{
  const pending = new Map();
  const shown = [];
  const recorded = [];
  const feed = createProgressFeed({
    initialPacket: 'older',
    decode(packet) { return new Promise(resolve => pending.set(packet, resolve)); },
  });
  const workspace = createTransferWorkspace({
    transport() {}, onCancel() {}, record() {}, showQueued() {},
    recordProgress: value => recorded.push(value.frame),
    showProgress: value => shown.push(value.frame),
  });
  workspace.select({ id: 'ordered', progressFeed: feed });
  feed.emit('newer');
  pending.get('newer')({ progress: 80 });
  await Promise.resolve();
  pending.get('older')({ progress: 10 });
  await Promise.resolve();
  assert.deepEqual(shown, [{ progress: 80 }]);
  assert.deepEqual(recorded, [{ progress: 80 }, { progress: 10 }]);
}

// The independent diagnostic consumer continues to ignore its own warm bootstrap.
{
  const deltas = [];
  const feed = createProgressFeed({ initialPacket: { progress: 1 } });
  const stop = collectProgressTelemetry(feed, frame => deltas.push(frame));
  feed.emit({ progress: 2 });
  stop();
  assert.deepEqual(deltas, [{ progress: 2 }]);
}

console.log('progress regression checks passed');
